import { DealStage, OPEN_STAGES, type Deal, type DealInput, type DealStageId, type PipelineSettings, type PipelineStage } from "../../types/work-sales"
import { roundMoney } from "./money"

/** Default chance of winning at each stage, in percent. */
export const STAGE_PROBABILITY: Record<DealStage, number> = {
  [DealStage.LEAD]: 10,
  [DealStage.QUALIFIED]: 25,
  [DealStage.PROPOSAL]: 50,
  [DealStage.NEGOTIATION]: 75,
  [DealStage.WON]: 100,
  [DealStage.LOST]: 0,
}

/** The pipeline a company starts with: the four default stages, stale after 14 days (CRM step 8). */
export const DEFAULT_PIPELINE: PipelineSettings = {
  stages: OPEN_STAGES.map((id) => ({ id, probability: STAGE_PROBABILITY[id] })),
  staleDays: 14,
}

export const pipelineOf = (settings?: { pipeline?: PipelineSettings } | null): PipelineSettings => settings?.pipeline ?? DEFAULT_PIPELINE

export const isClosedStage = (stage: DealStageId) => stage === DealStage.WON || stage === DealStage.LOST
export const isOpenDeal = (d: Pick<Deal, "stage">) => !isClosedStage(d.stage)

/** The open stage a deal sits in, when it is part of the pipeline. */
export const stageOf = (stage: DealStageId, pipeline: PipelineSettings = DEFAULT_PIPELINE): PipelineStage | undefined => pipeline.stages.find((s) => s.id === stage)

/** Won and lost deals are certain; open ones use their own chance or their stage's default. */
export function dealProbability(d: Pick<Deal, "stage" | "probability">, pipeline: PipelineSettings = DEFAULT_PIPELINE): number {
  if (d.stage === DealStage.WON) return 100
  if (d.stage === DealStage.LOST) return 0
  return d.probability ?? stageOf(d.stage, pipeline)?.probability ?? 0
}

export const weightedValue = (d: Pick<Deal, "stage" | "probability" | "amount">, pipeline: PipelineSettings = DEFAULT_PIPELINE) =>
  roundMoney((d.amount * dealProbability(d, pipeline)) / 100)

const dayOf = (iso: string) => iso.slice(0, 10)
const daysBetween = (from: string, to: string) => Math.round((Date.parse(`${to}T00:00:00Z`) - Date.parse(`${from}T00:00:00Z`)) / 86_400_000)

/** Whole days the deal has spent in its current stage. */
export const daysInStage = (d: Pick<Deal, "stageSince" | "createdAt">, today: string) => Math.max(0, daysBetween(d.stageSince ?? dayOf(d.createdAt), today))

/** An open deal that has not moved for longer than the company's limit. */
export const isStale = (d: Pick<Deal, "stage" | "stageSince" | "createdAt">, today: string, pipeline: PipelineSettings = DEFAULT_PIPELINE) =>
  isOpenDeal(d) && daysInStage(d, today) > pipeline.staleDays

export interface StageSummary {
  stage: DealStageId
  count: number
  amount: number
  weighted: number
  stale: number
}

/** Count, value, weighted value and stale deals per stage: the open stages in board order, then won and lost. */
export function pipelineByStage(deals: Deal[], pipeline: PipelineSettings = DEFAULT_PIPELINE, today?: string): StageSummary[] {
  return [...pipeline.stages.map((s) => s.id), DealStage.WON, DealStage.LOST].map((stage) => {
    const rows = deals.filter((d) => d.stage === stage)
    return {
      stage,
      count: rows.length,
      amount: roundMoney(rows.reduce((s, d) => s + d.amount, 0)),
      weighted: roundMoney(rows.reduce((s, d) => s + weightedValue(d, pipeline), 0)),
      stale: today ? rows.filter((d) => isStale(d, today, pipeline)).length : 0,
    }
  })
}

/** Open pipeline totals, win rate on closed deals, open deals past their expected close date, and stale deals. */
export function pipelineSummary(deals: Deal[], today: string, pipeline: PipelineSettings = DEFAULT_PIPELINE) {
  const open = deals.filter(isOpenDeal)
  const won = deals.filter((d) => d.stage === DealStage.WON)
  const lost = deals.filter((d) => d.stage === DealStage.LOST)
  const closed = won.length + lost.length
  return {
    openCount: open.length,
    openAmount: roundMoney(open.reduce((s, d) => s + d.amount, 0)),
    weighted: roundMoney(open.reduce((s, d) => s + weightedValue(d, pipeline), 0)),
    wonAmount: roundMoney(won.reduce((s, d) => s + d.amount, 0)),
    winRate: closed ? Math.round((won.length / closed) * 100) : null,
    overdue: open.filter((d) => d.expectedClose < today),
    stale: open.filter((d) => isStale(d, today, pipeline)),
  }
}

/** Throws the first problem with a deal. */
export function assertDeal(input: DealInput, pipeline: PipelineSettings = DEFAULT_PIPELINE) {
  if (!input.title?.trim()) throw new Error("Give the deal a name")
  if (!input.clientId) throw new Error("Choose a client")
  if (!(input.amount >= 0)) throw new Error("The amount can't be negative")
  if (!input.expectedClose) throw new Error("Set the expected close date")
  if (!isClosedStage(input.stage) && !stageOf(input.stage, pipeline)) throw new Error("This stage is not part of the pipeline")
  if (input.probability !== undefined && !(input.probability >= 0 && input.probability <= 100)) throw new Error("The chance of winning must be between 0 and 100%")
  if (input.stage === DealStage.LOST && !input.lostReason?.trim()) throw new Error("Say why the deal was lost")
}

export const MAX_STAGES = 10

/** Throws the first problem with a pipeline (CRM step 8). */
export function assertPipeline(pipeline: PipelineSettings) {
  const { stages } = pipeline
  if (stages.length < 1) throw new Error("Keep at least one open stage")
  if (stages.length > MAX_STAGES) throw new Error("A pipeline has at most 10 open stages")
  const ids = new Set<string>()
  const names = new Set<string>()
  for (const s of stages) {
    if (!s.id || ids.has(s.id) || isClosedStage(s.id)) throw new Error("Each stage needs its own id")
    ids.add(s.id)
    // the default stages may keep their translated label; added stages need a name
    const name = s.name?.trim()
    if (!name && !(OPEN_STAGES as readonly string[]).includes(s.id)) throw new Error("Give every stage a name")
    if (name) {
      const key = name.toLowerCase()
      if (names.has(key)) throw new Error("Two stages have the same name")
      names.add(key)
    }
    if (!(Number.isInteger(s.probability) && s.probability >= 0 && s.probability <= 100)) throw new Error("The chance of winning must be between 0 and 100%")
  }
  if (!(Number.isInteger(pipeline.staleDays) && pipeline.staleDays >= 1 && pipeline.staleDays <= 365)) throw new Error("A deal becomes stale after 1 to 365 days")
}
